import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { refreshContent } from '../../store/contentSlice';
import { toggleBookmark } from '../../store/activitySlice';
import { Helmet } from 'react-helmet';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import { useToast } from '../../contexts/ToastContext';
import { cn } from '../../utils/cn';

const GrowthVault = () => {
    const { addToast } = useToast();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const { isAuthenticated } = useSelector((state) => state.auth);
    const [searchQuery, setSearchQuery] = useState('');
    const [activeFilter, setActiveFilter] = useState('All');

    const vaultLessons = useSelector((state) => state.content.vault) || [];
    const instructors = useSelector((state) => state.content.instructors) || [];
    const bookmarks = useSelector((state) => state.activity.bookmarks);

    // Silent Refresher - Keep counts and content fresh in background
    useEffect(() => {
        const interval = setInterval(() => {
            dispatch(refreshContent());
        }, 30000); // Refetch every 30 seconds

        return () => clearInterval(interval);
    }, [dispatch]);

    const filters = ['All', 'Scholarships', 'Tech', 'Career', 'Exams'];

    const filteredLessons = vaultLessons.filter(lesson => {
        const matchesSearch = lesson.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            lesson.description.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesFilter = activeFilter === 'All' || lesson.category === activeFilter;
        return matchesSearch && matchesFilter;
    });

    const handleWatchLesson = (lesson) => {
        if (lesson.isProtected && !isAuthenticated) {
            addToast('Please Login to watch this premium vault lesson', 'info');
            navigate('/login');
            return;
        }
        navigate(`/academy/course/${lesson.id}`, { state: { course: lesson } });
    };

    const handleBookmark = (e, lesson) => {
        e.stopPropagation();
        if (!isAuthenticated) {
            addToast('Please Login to save lessons', 'info');
            navigate('/login');
            return;
        }

        const isBookmarked = bookmarks.some(item => item.id === lesson.id);

        if (isBookmarked) {
            addToast('Removed from Save for Later', 'info');
        } else {
            addToast('Saved for Later!', 'success');
        }

        dispatch(toggleBookmark({
            ...lesson,
            bookmarkedAt: new Date().toISOString()
        }));
    };

    return (
        <div className="min-h-screen bg-background flex flex-col">
            <Helmet>
                <title>Free Growth Vault | LUC Academy</title>
            </Helmet>
            <Header />

            <main className="flex-1 pt-8 pb-20">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <button 
                        onClick={() => navigate('/academy')}
                        className="flex items-center gap-2 text-muted-foreground hover:text-primary transition-colors mb-8 group"
                    >
                        <Icon name="ArrowLeft" size={18} className="group-hover:-translate-x-1 transition-transform" />
                        <span className="text-sm font-bold uppercase tracking-widest">Back to Academy</span>
                    </button>

                    {/* Header Section */}
                    <div className="text-center max-w-3xl mx-auto mb-16">
                        <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-secondary/10 border border-secondary/20 text-secondary mb-6 animate-in slide-in-from-bottom duration-500">
                            <Icon name="Zap" size={16} />
                            <span className="text-sm font-black uppercase tracking-widest italic">The Growth Vault</span>
                        </div>
                        <h1 className="text-4xl md:text-6xl font-black text-primary leading-tight mb-6 italic">
                            Quick Wins for <span className="text-secondary">Global</span> Success.
                        </h1>
                        <p className="text-lg text-muted-foreground">
                            A curated library of high-impact strategies, shortcuts, and templates
                            designed to help you level up in 15 minutes or less.
                        </p>
                    </div>

                    {/* Search and Filters */}
                    <div className="bg-card border border-border rounded-[2.5rem] p-6 mb-12 shadow-xl shadow-primary/5">
                        <div className="flex flex-col lg:flex-row gap-6">
                            <div className="flex-1 relative">
                                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground">
                                    <Icon name="Search" size={20} />
                                </div>
                                <input
                                    type="text"
                                    placeholder="Search the vault for topics (e.g. CV, Python, AI)..."
                                    className="w-full pl-12 pr-4 py-4 bg-background border-border rounded-2xl focus:ring-2 focus:ring-secondary/50 outline-none transition-all font-medium"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                />
                            </div>
                            <div className="flex flex-wrap gap-2">
                                {filters.map(filter => (
                                    <button
                                        key={filter}
                                        onClick={() => setActiveFilter(filter)}
                                        className={cn(
                                            "px-6 py-4 rounded-2xl text-sm font-black italic transition-all border",
                                            activeFilter === filter
                                                ? "bg-primary text-primary-foreground border-primary shadow-lg scale-105"
                                                : "bg-background border-border text-muted-foreground hover:border-primary/50"
                                        )}
                                    >
                                        {filter}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Results Grid */}
                    {filteredLessons.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-12">
                            {filteredLessons.map((lesson) => (
                                <div
                                    key={lesson.id}
                                    className="group bg-card border border-border rounded-[2rem] overflow-hidden hover:shadow-2xl transition-all duration-500 flex flex-col"
                                    onClick={() => handleWatchLesson(lesson)}
                                >
                                    <div className="relative aspect-video overflow-hidden">
                                        <img
                                            src={lesson.thumbnail}
                                            alt={lesson.title}
                                            className={cn(
                                                "w-full h-full object-cover transition-all duration-700 group-hover:scale-110",
                                                lesson.isProtected && !isAuthenticated && "blur-[1.5px] grayscale"
                                            )}
                                        />
                                        <div className="absolute inset-0 bg-black/20 group-hover:bg-black/0 transition-colors" />
                                        <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                            <div className="w-14 h-14 bg-white/95 dark:bg-black/80 backdrop-blur-md rounded-full flex items-center justify-center text-primary shadow-2xl scale-75 group-hover:scale-100 transition-transform duration-300">
                                                <Icon name={lesson.isProtected && !isAuthenticated ? "Lock" : "Play"} size={28} />
                                            </div>
                                        </div>

                                        {lesson.isProtected && !isAuthenticated && (
                                            <div className="absolute top-4 left-4 px-3 py-1.5 bg-primary text-primary-foreground rounded-lg text-[10px] font-black italic flex items-center gap-2 shadow-2xl">
                                                <Icon name="Lock" size={12} />
                                                LOCKED
                                            </div>
                                        )}

                                        <button
                                            onClick={(e) => handleBookmark(e, lesson)}
                                            className="absolute top-4 right-4 w-10 h-10 bg-white/90 dark:bg-black/60 backdrop-blur-md rounded-full flex items-center justify-center text-primary shadow-lg opacity-0 group-hover:opacity-100 transition-opacity hover:scale-110 active:scale-95 z-20"
                                        >
                                            <Icon
                                                name="Bookmark"
                                                size={16}
                                                fill={bookmarks.some(b => b.id === lesson.id) ? "currentColor" : "none"}
                                            />
                                        </button>

                                        <div className="absolute bottom-4 right-4 px-3 py-1 bg-black/60 backdrop-blur-md rounded-lg text-[10px] text-white font-black italic tracking-widest">
                                            {lesson.duration}
                                        </div>
                                    </div>

                                    <div className="p-6 flex flex-col flex-1">
                                        <div className="flex items-center gap-2 mb-3">
                                            <span className="text-[10px] font-black uppercase tracking-widest text-secondary px-2 py-1 bg-secondary/10 rounded-md border border-secondary/20">
                                                {lesson.category}
                                            </span>
                                        </div>
                                        <h3 className="text-xl font-bold text-primary mb-3 group-hover:text-secondary transition-colors italic leading-tight">
                                            {lesson.title}
                                        </h3>
                                        <p className="text-sm text-muted-foreground line-clamp-2 mb-6">
                                            {lesson.description}
                                        </p>

                                        {/* Instructor Footer */}
                                        <div className="pt-4 border-t border-border mt-auto flex items-center justify-between">
                                            {(() => {
                                                const instructor = instructors.find(i =>
                                                    (lesson.instructorId && i.id === lesson.instructorId) ||
                                                    (i.name === lesson.instructor)
                                                );
                                                return (
                                                    <div className="flex items-center gap-2">
                                                        <div className="w-8 h-8 rounded-full bg-muted border border-border overflow-hidden">
                                                            <img
                                                                src={instructor?.avatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(lesson.instructor || 'L')}&background=random`}
                                                                alt={lesson.instructor}
                                                                className="w-full h-full object-cover"
                                                            />
                                                        </div>
                                                        <div className="flex flex-col">
                                                            <span className="text-xs font-bold text-primary italic leading-none">{lesson.instructor}</span>
                                                            <div className="flex items-center gap-1 mt-0.5 opacity-80">
                                                                <Icon name="Users" size={10} className="text-secondary" />
                                                                <span className="text-[10px] font-black italic">{lesson.students || 0}</span>
                                                                <span className="text-[8px] uppercase font-bold tracking-tighter">Enrolled</span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            })()}
                                            <Button
                                                variant="ghost"
                                                className="p-0 h-auto font-black italic text-secondary group-hover:translate-x-1 transition-transform text-[10px]"
                                                iconName="ArrowRight"
                                                iconPosition="right"
                                            >
                                                WATCH
                                            </Button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-20 bg-muted/10 rounded-[3rem] border border-dashed border-border mb-12">
                            <div className="w-16 h-16 bg-muted/20 rounded-2xl flex items-center justify-center mx-auto mb-6 text-muted-foreground">
                                <Icon name="Frown" size={32} />
                            </div>
                            <h3 className="text-2xl font-bold text-primary mb-2">No Quick Wins Found</h3>
                            <p className="text-muted-foreground">Try adjusting your search or filters to find what you need.</p>
                            <Button
                                variant="outline"
                                className="mt-6"
                                onClick={() => { setSearchQuery(''); setActiveFilter('All'); }}
                            >
                                Reset All Filters
                            </Button>
                        </div>
                    )}

                    {/* Request CTA */}
                    <div className="p-12 bg-slate-900 dark:bg-slate-950 rounded-[3rem] text-center text-white relative overflow-hidden border border-white/10 shadow-2xl">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-secondary/20 blur-[100px] rounded-full" />
                        <div className="absolute bottom-0 left-0 w-64 h-64 bg-primary/10 blur-[100px] rounded-full opacity-50" />

                        <div className="relative z-10 max-w-2xl mx-auto">
                            <h2 className="text-3xl font-black italic mb-4">Want something specific?</h2>
                            <p className="text-slate-400 mb-8 text-lg leading-relaxed">
                                If there's a quick strategy or tool you want to see in the vault,
                                let us know and we'll record it for you.
                            </p>
                            <Button
                                variant="secondary"
                                className="px-10 h-14 font-black italic shadow-xl shadow-secondary/40 hover:scale-105 transition-transform"
                                onClick={() => addToast("Your request has been sent to our educators!", "success")}
                            >
                                REQUEST A QUICK WIN
                            </Button>
                        </div>
                    </div>
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default GrowthVault;
